using System.Text.Json.Serialization;
using AISmokingDetection.Common;

namespace AISmokingDetection.Model
{
    [JsonConverter(typeof(StringEnumConverter<ProcessingJobStatus>))]
    public enum ProcessingJobStatus
    {
        Queued,
        Processing,
        Completed,
        Failed
    }

    public class ProcessingJob
    {
        // Internal key. Never exposed to the AI service or to clients.
        public int ProcessingJobId { get; set; }

        // Public identifier generated by Backend B; used in every AI callback.
        public Guid JobId { get; set; } = Guid.NewGuid();

        // Source video (contract: videoId, cameraId, capturedAt, schemaVersion).
        public string VideoId { get; set; } = string.Empty;
        public int? CameraId { get; set; }
        public DateTimeOffset? CapturedAtUtc { get; set; }
        public string SchemaVersion { get; set; } = "1.0";

        // Internal media reference handed to the AI service (transfer "Option B").
        // Never returned to clients.
        public string? VideoReference { get; set; }

        public ProcessingJobStatus Status { get; set; } = ProcessingJobStatus.Queued;

        // Provenance reported by the AI service on completion.
        public string? ModelVersion { get; set; }
        public string? ConfigVersion { get; set; }
        public string? GalleryVersion { get; set; }

        public string DataOrigin { get; set; } = "recorded_video";

        public DateTimeOffset CreatedAtUtc { get; set; } = DateTimeOffset.UtcNow;
        public DateTimeOffset UpdatedAtUtc { get; set; } = DateTimeOffset.UtcNow;

        // Taken from the AI callback's updatedAt/completedAt; used for stale detection.
        public DateTimeOffset? LastStatusUpdatedAtUtc { get; set; }

        // Submission to the AI service (Backend B -> AI).
        public DateTimeOffset? SubmittedAtUtc { get; set; }
        public int SubmissionAttempts { get; set; }
        public string? LastSubmissionError { get; set; } // internal diagnostics only

        public DateTimeOffset? StartedAtUtc { get; set; }
        public DateTimeOffset? CompletedAtUtc { get; set; }

        public string? ErrorCode { get; set; }
        public string? ErrorMessage { get; set; } // safe, AI-provided message

        // Set by the monitor when no final callback arrived in time. Job state is NOT changed.
        public DateTimeOffset? StuckFlaggedAtUtc { get; set; }

        // Navigation: one job produces 0..N incidents.
        public ICollection<Incident> Incidents { get; set; } = new List<Incident>();
    }
}
